INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_gravitas', 'gravitas', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_gravitas_0', 'e_gravitas', 0, 'gravitas', '[]', 'Weight and seriousness in how a person carries themselves, such that a room treats what they say as consequential. It comes from bearing under pressure rather than from rank or volume.', 'Never said about yourself, and rarely to someone''s face. As feedback it is close to unfalsifiable and often a proxy for resembling the people already in the senior seats, so if you use it in a development conversation you owe the person a concrete behaviour to work on. Said of a peer in a standup it sounds arch; keep it for rooms where the stakes are real.', 'He took the audit question with real gravitas, which is why the board stopped pushing on it.', '[{"text":"A new director takes a hostile question from the board without flinching, and you want the word for what made the room settle.","setting":"work"},{"text":"You are telling a colleague why a senior audience did not take her recommendation seriously, and it was not the content.","setting":"work"},{"text":"A sponsor asks what is missing from the candidate who is technically the strongest on the shortlist.","setting":"work"},{"text":"A friend describes a wedding speech given by someone whose bearing made the whole room go quiet.","setting":"life"},{"text":"Watching an actor play a judge, you want the word for the weight he carries that the younger cast do not.","setting":"life"}]', '["Confidence in your own judgement, of the kind that lets you keep going when a room is plainly unconvinced.","The authority that arrives with a title: what a room concedes to whoever sits at the top of the chart before they have said anything.","Skill at reading a room as it moves and adjusting on the spot, so that what you say lands with the people actually in front of you. It is a sensitivity aimed outward at the audience rather than anything you carry in yourself.","A reputation built entirely out of past results, so that a room extends credit to your next claim on the strength of the last three. It is a ledger other people keep on you, and it survives a badly handled meeting intact.","A serious problem that has to be dealt with straight away, where the cost of leaving it another day is plainly higher than the cost of acting on incomplete information. It describes the weight of the thing in front of a group, not anything about the person raising it."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
