INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_executive_presence_finesse', 'executive presence/finesse', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_executive_presence_finesse_0', 'e_executive_presence_finesse', 0, 'executive presence', '[]', 'The quality of coming across as someone a decision can be handed to: composed under pressure, brief, and answering the question actually asked. It is judged in minutes, mostly on how you handle being challenged rather than on what you know.', 'One of the few phrases you can only ever say about someone else. As feedback it is notoriously vague and is often heard as be more like us, so it lands as a coded judgement unless you attach a concrete behaviour to it: cut the preamble, lead with the recommendation, stop narrating your working. Do not use it as a polite cover for a decision you have already made about someone.', 'Her content is watertight; what we are coaching is executive presence, starting with not burying the ask on slide nine.', '[{"text":"A brilliant engineer keeps losing the room in front of the investment committee, and you need the name for the thing he is missing.","setting":"work"},{"text":"Your manager asks what separates two candidates for a director role whose track records are identical.","setting":"work"},{"text":"You are designing a coaching plan for someone who knows more than anyone in the room but is never the one the MD turns to.","setting":"work"},{"text":"A friend preparing for a panel interview asks what the panel is really judging in the first two minutes.","setting":"life"}]', '["Formal authority handed down by a senior leader, so that you can commit the organisation to something without going back for permission.","Deep command of the technical detail in your own area, to the point where nobody in the room can correct you on it. It is expertise measured by depth rather than by bearing.","The visible backing of a senior figure, so that people read your request as carrying their weight rather than only your own. What it buys you belongs to whoever stands behind you and can be withdrawn the moment they change their mind.","Comfort in front of a large audience: the ability to hold a stage, keep a thousand people with you and land the last line on time without notes. It is a performing skill measured by the size of the room, and it says nothing about how you behave among six people deciding where the money goes.","A track record substantial enough that it argues for you before you open your mouth, so that a proposal with your name on it starts a step ahead of the same proposal from anyone else. It is accumulated evidence held in other people''s memories, built over years rather than read off you in the first few minutes."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_executive_presence_finesse_0_recognition', 's_executive_presence_finesse_0', 'recognition', NULL, NULL, 6, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_executive_presence_finesse_0_reverse', 's_executive_presence_finesse_0', 'reverse', NULL, NULL, 7, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_executive_presence_finesse_0_production', 's_executive_presence_finesse_0', 'production', NULL, NULL, 8, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_executive_presence_finesse_1', 'e_executive_presence_finesse', 1, 'finesse', '[]', 'Handling something delicate so smoothly that the difficulty never shows. As a verb it also means getting past an obstacle by deftness rather than force.', 'The verb has a second life that can bite you: we finessed the numbers sounds to a sceptical audience like the problem was smoothed over rather than solved. Aim it at how something was handled, never at the substance itself, and keep it well away from auditors, risk committees and anything that will be read later.', 'He finessed the headcount question without promising anything, and the MD moved on.', '[{"text":"A colleague deflects a budget question without either lying or conceding ground, and you want the word for how deftly it was done.","setting":"work"},{"text":"You are describing how a tense vendor negotiation was closed with nobody losing face.","setting":"work"},{"text":"A friend steered her parents off a touchy subject at dinner with no argument at all.","setting":"life"},{"text":"A footballer beats a defender with one soft touch instead of pace, and you want the word for that kind of skill.","setting":"life"}]', '["Brute persistence that simply wears the other side down until they stop objecting.","Blunt honesty that clears the air quickly, said of the person willing to name the awkward thing out loud while everyone else studies the table.","A formal process for settling a disagreement, with defined steps and somebody empowered to decide at the end of it. It is machinery the organisation supplies rather than anything the person running it brings.","Willingness to commit while the information is still incomplete, on the view that the cost of waiting exceeds the cost of being partly wrong. It is a stance towards risk, not a way of handling anything delicately.","The knack of remembering names, families and small details and producing them at the right moment, so that people feel known. It is warmth deployed on purpose, and it works on the relationship rather than on the difficulty in front of you."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_executive_presence_finesse_1_recognition', 's_executive_presence_finesse_1', 'recognition', NULL, NULL, 9, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
