INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_top_brass', 'top brass', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_top_brass_0', 'e_top_brass', 0, 'top brass', '["the brass"]', 'The most senior people in an organisation, spoken of as a single group and almost always from below.', 'It always marks you as outside the group, which is the charm of it in a corridor or a team channel and the problem with it anywhere formal. In a paper write the executive committee; said to one of them directly it is either flippant or faintly insubordinate, and said with a sigh it tells everyone how you feel about a decision you are supposed to be carrying. Borrowed from the military, and informal to the point of being wry.', 'The brass are in the building on Thursday, so keep the demo to ten minutes and skip the architecture slide.', '[{"text":"You are warning your team in a channel that the most senior leaders in the firm will be sitting in on Thursday''s review, and you want the informal collective for them.","setting":"work"},{"text":"Over coffee a peer asks who actually killed the project, and the answer is people neither of you has ever met.","setting":"work"},{"text":"A friend complains that the decision to close her branch came from people at head office who have never once visited it.","setting":"life"},{"text":"Your uncle is telling army stories about the officers who came round for inspection, and you want the wry phrase for them.","setting":"life"}]', '["The layer of managers sitting between the floor and the executive, translating in both directions.","The founders of a company who are still in it day to day, running the place themselves.","Long-tenured staff who know how the place really works, and whose blessing a change quietly needs even though no chart says so. What they hold is knowledge of the plumbing rather than any rank.","The standing committee that signs off spending above a set threshold, meeting to a calendar and leaving a minute behind it. It names a decision-making body with a remit, not the people a place thinks of as senior.","The highest-performing team in a division, the one held up in the quarterly review as the example everyone else is meant to follow. It is a judgement about results over a period rather than a description of where anybody sits."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_top_brass_0_recognition', 's_top_brass_0', 'recognition', NULL, NULL, 12, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_top_brass_0_reverse', 's_top_brass_0', 'reverse', NULL, NULL, 13, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
