INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_buy_in', 'buy-in', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_buy_in_0', 'e_buy_in', 0, 'buy-in', '["buy in"]', 'Real agreement from the people whose cooperation the work needs, to the point where they will defend it when you are not in the room. It is a state of the people, not a decision recorded anywhere.', 'Not a synonym for sign-off. Claiming you have it when what you actually have is a signature is the kind of statement that collapses at the first delivery slip, and the collapse is public. Said downward it can also sound like you plan to manage people into agreeing rather than ask them, so be careful announcing that you need to get it from your own team.', 'We have the funding, what we do not have is buy-in from the two teams who would have to change how they release.', '[{"text":"The steering committee has approved your programme, but the two delivery leads whose work it changes still think it is a mistake.","setting":"work"},{"text":"You are explaining to a sponsor why a technically finished rollout has stalled: the people whose process it changes were never really with you.","setting":"work"},{"text":"Writing a plan, you need a word for the thing a signature on its own does not give you.","setting":"work"},{"text":"Your family agrees in principle to the mountain holiday, but half of them are plainly humouring you.","setting":"life"},{"text":"A neighbour wants the shared driveway resurfaced and asks what she needs from the other households before anyone spends a penny.","setting":"life"}]', '["Formal sign-off that unblocks the work, recorded somewhere anybody can point later at the date it was given.","A shared understanding of what the goal actually is, such that two teams describing it separately would describe the same thing.","Senior backing that spends real political capital on your behalf, so that an objection gets answered by somebody more powerful than the person raising it. It is one person''s weight, not the willingness of the many.","A vote taken to settle a disagreement that discussion has failed to settle, where the count decides and the losing side is expected to live with the result. What it produces is a recorded outcome, which is exactly what it cannot produce in the people who lost.","The point at which a change stops being reversible, because enough has been migrated, announced or spent that turning back would now cost more than going on. It is a property of the work''s own momentum, and it can be reached with everyone involved still privately unconvinced."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_buy_in_0_recognition', 's_buy_in_0', 'recognition', NULL, NULL, 15, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_buy_in_0_reverse', 's_buy_in_0', 'reverse', NULL, NULL, 16, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_buy_in_0_production', 's_buy_in_0', 'production', NULL, NULL, 17, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_sponsorship', 'sponsorship', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_sponsorship_0', 'e_sponsorship', 0, 'sponsorship', '["sponsor"]', 'A senior person putting their own standing behind a piece of work or a person, and spending it when the thing is contested. It covers both an executive sponsor who owns a programme''s outcome and the backing that puts someone''s name into a promotion discussion.', 'The line that matters: a mentor talks to you, a sponsor talks about you. Describing someone as your sponsor when all they have given is advice overstates what you have, and it is embarrassing when the room knows them better than you do. The word also means paid branding, so with a mixed audience say executive sponsor the first time and let the rest run short.', 'The programme has funding and it has sponsorship, so when finance pushed back last week it was not my fight alone.', '[{"text":"A director asks what the failed initiative was really missing, and the honest answer is that nobody senior owned it once it got hard.","setting":"work"},{"text":"You are advising a colleague who has no shortage of mentors and keeps being passed over, and you want the word for the thing mentoring is not.","setting":"work"},{"text":"Before starting a programme that cuts across three teams, you want one word for the senior commitment you will ask for beyond the budget.","setting":"work"},{"text":"A friend''s daughter is trying to break into an industry where advice is easy to come by and an opened door is not.","setting":"life"},{"text":"At a climbing club an experienced member vouches for a newcomer and puts her own standing behind them.","setting":"life"}]', '["Genuine agreement from the people who actually have to do the work, to the point where they will argue for it when you are not there.","Advice and guidance given privately to somebody less experienced, on how to read a situation and what to do next. Nothing of the giver''s own standing is put at risk by it.","Formal budget authority over a programme: the signature that releases the money and the right to stop releasing it. It is a control written into the finance process rather than anything a person chooses to spend on your behalf, and it stays with the role after the holder moves on.","Responsibility for the day-to-day delivery of a project: the person who runs the plan, chases the dependencies and is asked first when a date starts to slip. The job is to make the thing happen week by week, and it is done on organisation and follow-through rather than on any weight the person carries with the people above the programme.","A named contact who handles escalations once the normal route has failed, so that a stuck item has somewhere to go outside the usual queue. The role is a routing decision the organisation published in advance; it costs the person holding it nothing, and their name on the list carries no opinion about whether the thing being escalated deserves to succeed."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_sponsorship_0_recognition', 's_sponsorship_0', 'recognition', NULL, NULL, 18, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_sponsorship_0_reverse', 's_sponsorship_0', 'reverse', NULL, NULL, 19, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_sponsorship_0_production', 's_sponsorship_0', 'production', NULL, NULL, 20, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_cognizant', 'cognizant', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_cognizant_0', 'e_cognizant', 0, 'cognizant', '["cognisant"]', 'Aware of something and visibly taking it into account, especially something you were expected to have noticed. It says the thing was in view when the decision was made, not merely that you know it now.', 'A memo word, not a spoken one. Said aloud it sounds stiff and aware would do the same job, but in writing it earns its place because it puts on record that you knew and weighed something, which is exactly what an auditor or a regulator is reading for. Be careful claiming it after the fact about a risk you plainly missed, and note that a large IT services firm carries the name, so in a vendor conversation there will be a beat where someone thinks you meant them.', 'We are cognizant of the concentration risk, and the phased rollout is the answer to it.', '[{"text":"You are drafting a paper and want a formal way to record that the team already weighed the risk the committee is about to raise.","setting":"work"},{"text":"A regulator asks whether the implications were understood at the time, and they were.","setting":"work"},{"text":"Writing to a landlord about a repair, you want to acknowledge that he has other tenants without sounding casual about your own problem.","setting":"life"},{"text":"Explaining a decision to a family member, you want a slightly formal way of saying their situation was in view the whole way through.","setting":"life"}]', '["Able to reason a problem through step by step, holding several moving parts in mind at once without losing the thread.","Formally notified of something in writing, so that a record exists showing the message was sent and received.","Sceptical of a claim until somebody puts hard evidence in front of you, and willing to keep saying so while the rest of the room has already moved on. It reports a standing disposition towards proof rather than a state of having noticed anything in particular.","Considerate of how other people are feeling and adjusting what you say to fit it, so that a hard message lands without doing damage nobody needed. It is care aimed at the person in front of you rather than attention paid to a fact.","In agreement with a stated position, to the point of putting your name next to it in front of people who will hold you to it later. It reports where you finally landed on the question, not what you had in view while the question was being decided."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
