INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_incremental', 'incremental', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_incremental_0', 'e_incremental', 0, 'incremental', '["incrementally"]', 'Proceeding by small additions, each one standing on its own. It describes both a way of delivering work and the size of a gain.', 'The word has two temperatures and the room picks which one. About delivery it is a virtue; about results it is faint praise, and applied to a benefits case it is how a committee says not worth the money without having to argue. Decide which one your audience will hear before you use it about your own work. In a finance conversation it means something different again, the extra amount on top of the baseline rather than a small one.', 'The gains are incremental per release, and it is the compounding across two quarters that the case actually rests on.', '[{"text":"A committee asks how you will de-risk an eighteen-month programme, and your answer is small releases that each stand on their own.","setting":"work"},{"text":"You are describing model improvements that are real but modest, and you want the honest word for them before somebody else uses it against you.","setting":"work"},{"text":"You are explaining how you are learning a language: twenty minutes a night, nothing dramatic.","setting":"life"},{"text":"A friend asks whether the new phone is worth the upgrade, and every improvement in it is a small one.","setting":"life"}]', '["Happening all at once after a long build-up, with nothing usable before it.","Repeated identically each cycle, so that the tenth run looks exactly like the first one.","Growing faster the longer it runs, because every step makes the next one cheaper. The curve bends upward rather than climbing at an even rate.","Reversible at any point at no cost, so that you can undo a step and stand exactly where you started. It is a claim about the way back, not the way forward.","Delivered only once it is completely finished, on the view that a half-built thing is worth nothing to anybody. Nothing reaches a user in the meantime, however long the meantime turns out to be."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
