INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_progressive', 'progressive', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_progressive_0', 'e_progressive', 0, 'progressive', '["progressively"]', 'Advancing in stages, each stage going further than the last: a rollout that widens from one team to ten to everyone, or an interface that reveals more of itself as you need it. The emphasis is on the steady advance rather than on the size of any one step.', 'The word has a political life, so about people, policy or an organisation''s values it will be read that way whatever you meant, and in that reading it is a label rather than a description. Say phased or staged there. In a pricing or tax conversation it means something different again, rates that rise with the amount. Keep it for delivery and design, where the technical reading is the only one available.', 'We will do a progressive rollout, one desk this week, the floor next week, and the region only after two clean weeks.', '[{"text":"You are proposing to widen a release from one desk to a floor to the whole region, one step at a time, and want the adjective for that shape of rollout.","setting":"work"},{"text":"A designer asks what to call an interface that shows the simple case first and reveals the advanced controls only when they are asked for.","setting":"work"},{"text":"In a risk paper you need a word for exposure that grows in planned stages rather than arriving all at once.","setting":"work"},{"text":"Your optician is describing lenses whose strength changes gradually from the top of the lens to the bottom.","setting":"life"},{"text":"A friend''s training plan adds a little more distance every week, and you want the adjective for that kind of build-up.","setting":"life"}]', '["Applied to everyone at the same moment, so that the change either works for the whole population at once or fails for all of it at once.","Rolled back automatically the moment the numbers turn, without anybody having to be woken up to make the call. The cleverness sits in the retreat rather than in how the thing went out.","Made of independent parts that can be built and shipped separately, so that one piece changing does not drag the rest along with it. It describes how the thing is put together rather than the order in which it reaches people, and a set of parts can go out to everybody on the same morning.","Improving in quality while staying exactly the same in scope, so that the thing does what it always did and simply does it better each time you look. The gain is depth on a fixed footprint, which is a different axis altogether from reaching further with every step.","Repeated over and over until a target is finally met, each pass looking much like the last one and the stopping rule set by the number rather than by the stage. What defines it is the return to the same ground, so a run that never reaches the target simply goes round again, which is the opposite of arriving somewhere new each time."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
