INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_ducks_in_a_row', 'ducks in a row', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_ducks_in_a_row_0', 'e_ducks_in_a_row', 0, 'ducks in a row', '["get your ducks in a row","ducks lined up"]', 'The preparation done in advance of a moment where a gap would cost you: the approvals, the numbers and the people all settled beforehand. It is about readiness, not about the thing you are getting ready for.', 'It is homely and slightly folksy, which makes it warm between peers and patronising downward, and telling a senior stakeholder to get their ducks in a row implies they are disorganised. It belongs to speech: in a written paper it reads as though you could not be bothered to name which preparation you actually meant.', 'Before this goes to the committee let us get our ducks in a row on the cost model and the security sign-off.', '[{"text":"Two weeks before a board paper you want to tell your team informally that every approval, number and sign-off has to be settled first.","setting":"work"},{"text":"A peer is about to ask for headcount with no business case and no hiring plan ready behind it.","setting":"work"},{"text":"A friend is buying a flat and has not yet sorted the mortgage, the survey or the solicitor.","setting":"life"},{"text":"Before a family trip abroad you want a phrase for getting the passports, the insurance and the bookings all settled in advance.","setting":"life"}]', '["A queue of tasks all waiting on the same person, moving only as fast as that one diary allows them to move.","Agreement reached quietly before a meeting starts, so that the discussion in the room only ratifies what was settled outside it.","A sequence of checks run automatically before a release, each one able to stop the thing going out on its own. It is machinery wired into the pipeline rather than anything a person has arranged by hand.","The order in which speakers will take an item, agreed beforehand so that nobody talks over anybody and the most senior view does not land first. It settles the choreography of the session rather than whether the material behind it holds.","A backlog cleared down before any new work is accepted, so that the team starts the next thing without carrying the last one on its back. The point is finishing what is already open, which is about closing things out rather than about being ready for a moment ahead of you."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_ducks_in_a_row_0_recognition', 's_ducks_in_a_row_0', 'recognition', NULL, NULL, 54, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
