INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_watch_outs', 'watch outs', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_watch_outs_0', 'e_watch_outs', 0, 'watch outs', '["watch-outs","watchouts","watch out"]', 'The short list of things most likely to go wrong or catch people off guard, given to an audience in advance so that nobody is surprised. Lighter than risks: a risk needs an owner and a mitigation, a watch out needs only attention.', 'This is consultant and steering-committee register, natural on a slide and slightly odd said aloud anywhere else. The real trap is using it as a softer label for something that is actually a risk: relabelling it removes the owner and the mitigation, and a watch out is what an unmanaged problem is called right up until it fires. Flag it this way only when attention genuinely is the whole response.', 'Two watch outs before we start: the data refresh lands mid-demo, and Legal has not seen the retention wording yet.', '[{"text":"You are opening a steering committee update and want to flag two things likely to trip the group up, short of raising them as formal risks.","setting":"work"},{"text":"A colleague is taking over your demo next week and needs to know the two places it usually goes wrong.","setting":"work"},{"text":"Writing a one-page handover, you need a heading for the short list of things that catch people by surprise.","setting":"work"},{"text":"A friend is renting a flat in a neighbourhood you know well, and you want to name two things she should keep an eye on before she signs.","setting":"life"}]', '["Risks with a named owner and a mitigation plan, tracked in a register somebody reviews on a fixed cycle.","Metrics reviewed at the end of every week, so that a drift shows up while there is still time to do something about it.","Conditions that automatically halt a release the moment they are met, written down in advance precisely so that nobody has to make the call under pressure. They are a brake wired into the process, not a heads-up handed to an audience.","Lessons recorded after a piece of work has finished, gathered in a session where the team says what it would do differently next time. They face backwards over something already done, and their value depends on somebody reading them before the next one starts.","Items deliberately deferred to a later phase, listed so that nobody mistakes their absence for an oversight and quietly builds them anyway. The list draws the edge of what is in scope, which is a statement about what will not be delivered rather than about what might go wrong with what will."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_watch_outs_0_recognition', 's_watch_outs_0', 'recognition', NULL, NULL, 57, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
