INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_watch_outs_0_production', 's_watch_outs_0', 'production', NULL, NULL, 59, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_lean_on', 'lean on', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_lean_on_0', 'e_lean_on', 0, 'lean on', '["leaned on","leaning on"]', 'To rely on someone or something to carry part of the weight: a person''s expertise, an existing system, a relationship, instead of building or bearing it yourself.', 'The same phrase also means to apply pressure, and only the object and your tone separate them, so we leaned on the vendor and we leaned on Legal are two different sentences. Save the pressure reading for suppliers, never colleagues. And when you say it about a person in front of their manager, name what they actually gave you, otherwise it sounds like you handed them your job.', 'For the regulatory wording we leaned on Legal rather than inventing our own language.', '[{"text":"You are explaining how the team delivered a compliance section without hiring an expert: somebody else''s knowledge carried it.","setting":"work"},{"text":"In a design discussion you want to say the new service should use the identity system that already exists rather than reinvent it.","setting":"work"},{"text":"A director asks how you will cover the gap while the role is unfilled, and the answer is a colleague''s goodwill and time.","setting":"work"},{"text":"A friend is going through a hard month and you want to tell them to draw on the people around them.","setting":"life"},{"text":"You are describing how you got through a house move on your brother''s van and two very patient friends.","setting":"life"}]', '["To hand a task formally to another team, with the transfer recorded and a date attached to it.","To copy an approach that worked somewhere else, instead of designing one for the situation actually in front of you.","To simplify a process by stripping steps out of it until what is left is only what somebody would miss. The weight goes away rather than moving onto something else.","To take on extra work so that a colleague does not have to carry it, usually without being asked and usually without it showing up anywhere. It moves the load towards you, which is the opposite direction.","To build your own version of something you currently depend on, so that the dependency disappears and the work sits inside your own team from then on. It removes the support rather than putting any weight on it."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
