INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_lean_on_0_reverse', 's_lean_on_0', 'reverse', NULL, NULL, 61, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_lean_on_0_production', 's_lean_on_0', 'production', NULL, NULL, 62, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_blanket_approval_carte_blanche', 'blanket approval/carte blanche', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_blanket_approval_carte_blanche_0', 'e_blanket_approval_carte_blanche', 0, 'blanket approval', '["carte blanche"]', 'Permission given once and in advance to cover a whole class of decisions, so that each one does not have to come back for review. The point is the scope of the freedom rather than the size of any single decision inside it.', 'Claiming it is far riskier than having it. Tell a committee you have blanket approval and you have invited someone to go and check, and permissions of this shape almost always turn out to have had conditions attached that nobody wrote down. Carte blanche carries a whiff of indulgence on top: about someone else it implies they are unsupervised, about yourself it sounds like a boast.', 'We do not have blanket approval for production data, it is per use case, and the last one took three weeks.', '[{"text":"A team believes one sign-off last quarter covers every future use of customer data, and you need the phrase for what they think they have.","setting":"work"},{"text":"A sponsor offers to let you make all the tooling decisions for the year without coming back to him each time.","setting":"work"},{"text":"You are drafting a governance note about which decisions need a case-by-case review and which do not.","setting":"work"},{"text":"A friend''s parents have told her to plan the anniversary party however she likes, with no limit on the budget.","setting":"life"},{"text":"A neighbour is letting the builder choose every fitting in the new kitchen, with no say in it at all.","setting":"life"}]', '["Permission granted for one specific case only, with the next one having to come back and ask again from the start.","A decision taken without consulting anybody who might have objected, on the view that asking would have cost more time than it was worth.","Provisional agreement pending a formal sign-off, enough to start work against but not enough to spend against. What it hands you is the nod, with the actual permission still sitting somewhere ahead of you.","A budget set aside for needs nobody has foreseen, drawn on when something turns up that the plan never contained. It is money held in reserve rather than permission held in advance, and each draw still has to be released case by case.","A time-limited exemption from a rule, granted because the rule would otherwise block something urgent, and expiring on a date written into the grant itself. The exception is narrow and the clock is the whole point of it, which is nearly the opposite of a freedom whose value lies in how wide it runs."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_blanket_approval_carte_blanche_0_recognition', 's_blanket_approval_carte_blanche_0', 'recognition', NULL, NULL, 63, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
