INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_elucidate', 'elucidate', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_elucidate_0', 'e_elucidate', 0, 'elucidate', '[]', 'To make something already said or written finally make sense, by laying out the reasoning or the detail underneath it. You elucidate a thing that is present but opaque, not a thing that is missing.', 'It is a formal word, and spoken it can sound like you are performing. Asking a person to elucidate is a half-step colder than asking them to explain, because it says they were not clear; it lands better in writing, and better aimed at a document than at the author. It also promises the thing gets clearer, not longer. More words that still do not land is the opposite move, and someone will say so.', 'The deck lands the recommendation but never elucidates how we got to that number, and that is the part the committee will push on.', '[{"text":"A steering committee accepts your recommendation but says the reasoning behind one number is a black box. You are writing back to promise the appendix will open it up.","setting":"work"},{"text":"A colleague''s design doc states a decision without showing the trade-off behind it, and in review you want to ask them to bring that reasoning into the open.","setting":"work"},{"text":"Your father repeats the conclusion of a health article without any of what it argued, and you want him to take you through the actual case it made.","setting":"life"},{"text":"A book group is stuck on a chapter that one member plainly understood, and you want to invite them to open it up for everyone.","setting":"life"}]', '["To restate something at greater length, on the assumption that more words will do what fewer of them did not.","To condense a long argument down to its essentials, so that somebody can carry the whole of it out of the room in one sentence.","To make something deliberately hard to follow, so that the plain version of it never quite surfaces. The direction of travel is away from understanding rather than towards it, and the effort is the giveaway.","To supply the evidence that backs up a claim, so that somebody else can check the working rather than simply take your word for it. What was missing was the proof, and the claim itself was perfectly clear all along.","To infer a conclusion from information that is plainly incomplete, filling the gaps with judgement and marking which parts were filled that way. You are producing something that was never on the page, which is a different job from making sense of what is."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
