INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_bolster', 'bolster', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_bolster_0', 'e_bolster', 0, 'bolster', '["bolstered","bolstering"]', 'To add support to something that already stands but is not standing well enough on its own: a case, a claim, a balance, morale. What was there stays; you are putting weight behind it.', 'It concedes the weakness. Say you want to bolster the business case and you have told the room the case is currently thin, which is fine when you mean it and expensive when you did not. It also wants abstract objects: you bolster an argument, reserves, or confidence, and you do not bolster a server or a deadline.', 'The numbers are directionally right, but one more independent source would bolster them before this goes to the board.', '[{"text":"Your recommendation rests entirely on a single vendor''s figures, and you are proposing a second, independent source so it survives scrutiny.","setting":"work"},{"text":"In a review a junior colleague makes a correct point that lands weakly, and you want to put your own evidence behind it without taking the point over.","setting":"work"},{"text":"A friend''s visa application is complete but unconvincing on its own, and you are suggesting a letter from their employer go in alongside it.","setting":"life"},{"text":"Your savings would just about cover six months without work, and your partner asks what you plan to do about the margin before you resign.","setting":"life"},{"text":"A nervous friend ran their speech past three people the night before, and you are describing what that did for them.","setting":"life"}]', '["To restate a claim more forcefully than before, without putting anything new behind it.","To replace something that is failing with a stronger alternative, so that what was there before is gone by the end of it.","To defend a position that is under direct challenge, answering the objection in front of the people who raised it. The work is done in the argument rather than on the thing being argued about.","To overstate how strong a case actually is, describing as settled something that is merely arguable and hoping nobody looks. Nothing about the case changes; only the account other people are given of it does.","To hold something up temporarily until it can stand on its own, with the support taken away by design once the thing is ready to do without it. What defines it is the intention to remove the prop, which is no part of putting weight behind something."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_bolster_0_recognition', 's_bolster_0', 'recognition', NULL, NULL, 78, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_bolster_0_reverse', 's_bolster_0', 'reverse', NULL, NULL, 79, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_bolster_0_production', 's_bolster_0', 'production', NULL, NULL, 80, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_verbose', 'verbose', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_verbose_0', 'e_verbose', 0, 'verbose', '["verbosity"]', 'Using far more words than the point needs. It is a judgement about the words, not the content, so something can be entirely correct and still be verbose, which is what makes it a chore to read.', 'It criticises the writer, not only the writing, and it stings more than long or dense. Said out loud about someone''s answer while others are listening it is close to rude; keep it for drafts, for logs, and for your own work. It also has a flat, non-insulting life in engineering, where verbose output or verbose logging just means detailed, so in a mixed room make clear which of the two you mean.', 'It is accurate, but it is verbose. The committee will read the opening paragraph and stop.', '[{"text":"A colleague''s weekly update runs to four paragraphs where two lines would do, and you are giving them the feedback privately.","setting":"work"},{"text":"You reread your own memo before sending it and notice it takes half a page to reach the ask.","setting":"work"},{"text":"A friend forwards you the terms of a phone contract that says almost nothing across two thousand words.","setting":"life"},{"text":"You gave up on a novel a hundred pages in because every scene took three pages to move an inch.","setting":"life"}]', '["Written in unnecessarily technical language, so that a general reader stalls on the vocabulary rather than the argument.","Delivered so fast that nobody can follow it, the argument fine on the page and gone by the time you look up from your notes.","Deliberately vague so as to avoid committing to anything, phrased so that either outcome can afterwards be read as the one that was meant. The evasion is the point of it, and it can be managed in very few words.","Formal to the point of coldness, correct in every particular and offering the reader nothing at all to hold on to. It is a complaint about the temperature of the writing rather than about how much of it there is.","Full of confident claims with nothing standing behind any of them, so that the register stays certain and the evidence never arrives. What is wrong is the gap between the assurance and the support, which a short paragraph manages as easily as a long one."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_verbose_0_recognition', 's_verbose_0', 'recognition', NULL, NULL, 81, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_verbose_0_reverse', 's_verbose_0', 'reverse', NULL, NULL, 82, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_verbose_0_production', 's_verbose_0', 'production', NULL, NULL, 83, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_amenable', 'amenable', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_amenable_0', 'e_amenable', 0, 'amenable', '[]', 'Open to something without having agreed to it: willing to go along if it comes to that. Of a problem or a dataset rather than a person, it means well suited to a particular treatment.', 'Its softness is the whole point and it evaporates in the retelling. Tell a room the CFO was amenable and half of them will hear that he agreed, and when he objects three weeks later that gap is yours to explain. It also quietly grades the person, so it reads better about how an idea was received than about a senior colleague''s temperament.', 'The MD was amenable to a phased rollout, though I want to be clear that nothing is signed.', '[{"text":"You sounded out a director in the corridor about moving the deadline and they did not push back. You are reporting that to your team without overstating what you have.","setting":"work"},{"text":"A vendor has hinted they could flex on the licence terms, and your sponsor asks how the conversation went.","setting":"work"},{"text":"A dataset turns out to be clean and regular enough that a simple model handles it, and you are explaining in review why nothing more elaborate is needed.","setting":"work"},{"text":"You floated Christmas at your parents'' rather than hers and your partner did not object. Her sister asks whether it is settled.","setting":"life"},{"text":"You asked the landlord about getting a cat and got a shrug rather than a no.","setting":"life"}]', '["Eager to take on additional responsibility, and saying so before anybody has offered it.","Easily talked out of a position you held, so that the last person to make a case tends to be the one who carries you.","Formally committed to a course of action, on the record and in a form other people will hold you to later. The question of willingness closed some time ago, which is the whole difference.","Able to be corrected or revised later without much cost, so that getting it wrong now turns out not to be expensive. It is a property of how easily a thing can be changed, said of the decision rather than of anybody making it.","Pleasant in manner but slow to act, agreeable in every conversation and reliably still exactly where you left them a fortnight later. The complaint is about the distance between how somebody sounds and what they actually do, which is a judgement rather than a state of being open to something."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_amenable_0_recognition', 's_amenable_0', 'recognition', NULL, NULL, 84, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_amenable_0_reverse', 's_amenable_0', 'reverse', NULL, NULL, 85, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_amenable_0_production', 's_amenable_0', 'production', NULL, NULL, 86, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_unequivocal', 'unequivocal', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_unequivocal_0', 'e_unequivocal', 0, 'unequivocal', '["unequivocally"]', 'Admitting only one reading. Said of a statement, a decision, or evidence that has been put in a form nobody can walk back or interpret a second way.', 'It is as much a claim about your own certainty as about the thing, which is an invitation: call the results unequivocal and one awkward case takes the whole sentence down with it. It belongs to statements and evidence rather than to people, so support, instructions, and findings can be unequivocal and a sponsor cannot. Used about your own view it can also come across as shutting the discussion rather than winning it.', 'The board came back unequivocal on this: no client data leaves the tenancy, under any structure.', '[{"text":"You are relaying a decision from the top that came with no conditions attached, and people keep asking where the wiggle room is.","setting":"work"},{"text":"A regulator''s letter allows exactly one reading, and you are summarising it for a team that would very much like it to allow two.","setting":"work"},{"text":"Your doctor''s advice about the medication came without a single hedge, and a relative keeps hunting for the loophole.","setting":"life"},{"text":"A friend asks whether your partner is genuinely on board with the move. She said yes in a way that left nothing open.","setting":"life"}]', '["Stated with great force or at great volume, so that nobody in the room misses it.","Agreed by everybody in the room, with no dissent left over to be recorded anywhere afterwards.","Supported by more than one independent line of evidence, so that every check points the same way. The strength sits in the corroboration rather than in the wording.","Given without any explanation or reasoning attached, so that the answer stands there on its own and the argument for it does not. It says what was withheld rather than how the words can be read.","Impossible to challenge on procedural grounds, because the right people were consulted and every step of it was properly minuted. The protection lies in the process behind the decision, and the words announcing it may still be read two ways."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
