INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_surreptitiously', 'surreptitiously', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_surreptitiously_0', 'e_surreptitiously', 0, 'surreptitiously', '["surreptitious"]', 'Done quietly so as not to be seen doing it, usually because being seen would stop it or embarrass you. The concealment is of the act, not necessarily of anything shameful in it.', 'It supplies a motive for the hiding, so aimed at a colleague it is an accusation wearing the clothes of an adverb. About systems it is heavier still: an agent that surreptitiously wrote to the database will be read as a security finding rather than a quirk, and the sentence outlives the meeting. About yourself it is usually light and self-deprecating, which is where most of its safe uses are.', 'Nobody signed anything off. A team had been surreptitiously pointing production traffic at the new index for a month.', '[{"text":"You checked the football score under the table during your niece''s school play.","setting":"life"},{"text":"A friend has been moving small amounts out of the joint account for months to pay for a surprise trip.","setting":"life"},{"text":"Someone at the next table is clearly photographing the menu prices and clearly does not want to be seen doing it.","setting":"life"},{"text":"You want to describe how a team kept an old system quietly running long after it was declared dead, and you are choosing how hard to make that land.","setting":"work"}]', '["Done without asking anybody first, though in full view of everyone it affects.","Done by hint rather than by statement, so that the other person has to work out for themselves what was actually meant.","Done informally rather than through the proper channel, in the open but without the paperwork the process would normally demand. The shortcut is procedural, and everybody can see it being taken.","Done in a rush, with the usual checks skipped to make a date somebody else set. The corners cut are visible at the time, and they turn up again months later in whoever inherits the job of putting them right.","Done reluctantly and only because you were told to, with the disagreement left obvious to everyone in the room. The manner carries the objection that the words themselves are not permitted to carry, and it is meant to be read that way by the person who gave the instruction."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
