INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_idempotent', 'idempotent', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_idempotent_0', 'e_idempotent', 0, 'idempotent', '["idempotency","idempotence"]', 'Safe to run more than once: the second and third run leave the system in exactly the state the first one did. It is a claim about the end state, not a claim that the later runs do nothing.', 'It is a promise other people design against. Say an endpoint is idempotent and someone will put a retry in front of it, so if a second call charges the card again or appends a second row, their outage is your sentence. Outside an engineering room it buys you nothing: with a sponsor say the job is safe to re-run, and keep the word for the people who will build on it.', 'The ingestion job has to be idempotent. The scheduler will retry it on failure and we cannot end up with last night''s rows twice.', '[{"text":"Two overlapping schedules mean a batch job can be triggered twice in the same hour, and you are writing the one property it must have before you will sign it off.","setting":"work"},{"text":"A payments integration will be retried automatically on timeout, and you are naming the requirement that keeps a customer from being charged two or three times.","setting":"work"},{"text":"In a design review someone proposes an endpoint that appends a row on every call, and you want to name what it is missing before it goes near production.","setting":"work"}]', '["Safe for several copies to run at the same moment, because no two of them ever touch the same record.","Able to be undone cleanly afterwards, leaving the system as it stood before anything started and leaving no sign that it ever did.","Either finishing in full or leaving nothing behind at all, so there is no condition in which half the work has landed and half has not. It is a claim about what a failure is allowed to leave.","Able to pick up from the last checkpoint after an interruption rather than starting again at the beginning, so that a long job survives a restart without losing the hours already spent on it. The saved position is the whole trick.","Carrying nothing between calls, so any instance can serve any request and it does not matter which machine handled the one before. This is what lets you add capacity by adding copies rather than by making a single copy bigger, and it is why the load balancer needs no memory."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
