INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_community_of_practice_vs_center_of_excellence', 'community of practice vs center of excellence', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_community_of_practice_vs_center_of_excellence_0', 'e_community_of_practice_vs_center_of_excellence', 0, 'community of practice', '["CoP","communities of practice"]', 'A voluntary group of people who do the same kind of work and meet to trade what they are learning. It has no mandate, no budget and no authority over anyone; its only claim is that people keep turning up because it is useful.', 'Because it is voluntary you cannot hold it to a deliverable, so promising a steering group that one will own the standards promises something it has no power to enforce. Give it a budget, headcount and sign-off rights and you have built the other thing, and should say so rather than keeping the friendlier name over it. It also fails quietly: naming one costs nothing, and an empty calendar invite six months on is visible to everybody.', 'The prompt engineering group is not a governance body. It is a community of practice, and it works precisely because nobody has to come.', '[{"text":"Engineers in four product teams keep solving the same problem separately, and you want to propose a standing forum with no mandate and optional attendance.","setting":"work"},{"text":"A director asks what to call the monthly session where people demo what they tried and what failed, and you want a name that promises sharing rather than authority.","setting":"work"},{"text":"A sponsor asks how the data scientists scattered across four teams will stay aligned when you have no authority over any of them.","setting":"work"}]', '["A rotating assignment where people spend a fixed spell embedded in another team and then come back with whatever they picked up.","A shared channel where anyone can put a question and whoever is on duty that week is expected to answer it. The rota is published, so nobody has to work out who to ask.","A standing committee that reviews proposals against a published bar and can send them back for rework. Attendance is part of the job for the people on it, and what it decides binds the teams that come to it.","A reporting line drawn by discipline, so that specialists sit inside product teams day to day but are managed, promoted and paid through their craft. Membership is not something anyone opts into; it is simply where your name appears on the chart.","An outside professional body that sets a syllabus and certifies whoever passes it, so the qualification belongs to the person rather than to the employer. Its authority comes from the fact that other firms recognise the same badge, which is also what makes it worth the fee."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_community_of_practice_vs_center_of_excellence_0_recognition', 's_community_of_practice_vs_center_of_excellence_0', 'recognition', NULL, NULL, 105, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_community_of_practice_vs_center_of_excellence_0_reverse', 's_community_of_practice_vs_center_of_excellence_0', 'reverse', NULL, NULL, 106, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_community_of_practice_vs_center_of_excellence_0_production', 's_community_of_practice_vs_center_of_excellence_0', 'production', NULL, NULL, 107, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_community_of_practice_vs_center_of_excellence_1', 'e_community_of_practice_vs_center_of_excellence', 1, 'center of excellence', '["CoE","centre of excellence","centers of excellence"]', 'A funded, staffed team that concentrates a scarce capability in one place and sets how it is done everywhere else. It owns the standards, and usually a queue of work from the teams it serves.', 'The name claims authority and quality at once, and both get tested. Stand one up and other teams hear that they now need your permission, so it concentrates resentment as fast as it concentrates skill; the credible version comes with a stated plan to hand the capability back. Used for a group of enthusiasts with no funding and no headcount, it is corporate inflation, and the senior people in the room can smell it.', 'If we stand this up as a center of excellence, every model deployment routes through eight people, and those eight people are the constraint by March.', '[{"text":"Four teams have each hired one data scientist and none of them can staff a whole project. You are proposing a single funded team that serves all four and owns the standards.","setting":"work"},{"text":"A sponsor wants one accountable home for model risk, with real headcount attached, and asks what to call it in the operating model.","setting":"work"},{"text":"You are warning a steering group that routing every deployment through one specialist team will make that team the bottleneck by spring, and you want to name the pattern you are warning against.","setting":"work"}]', '["A service desk that takes routine requests from across the business and works them in the order they arrive.","A pilot team stood up to prove a technology works before anyone commits real money to it, and disbanded once that question has an answer.","A cross-functional squad assembled for one programme and dissolved the week it ships, so its people go back to the teams they were borrowed from. Nothing about it was meant to outlast the delivery.","The team whose numbers currently lead the scorecard, held up at the quarterly review so that everyone else can see what good looks like. The status is earned each quarter and moves to whoever is ahead in the next one.","An outside firm brought in on a statement of work because the skill is not worth hiring for permanently. It leaves when the contract ends, and everything it learned on the way leaves with it unless somebody insisted on writing it down first."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
