INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_first_principles', 'first principles', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_first_principles_0', 'e_first_principles', 0, 'first principles', '["from first principles"]', 'The small set of things you know to be true once precedent, analogy and how it is normally done have been stripped out. Working from first principles means rebuilding the answer out of those, rather than adapting somebody else''s answer.', 'The phrase has become a status move. Announcing that you are going back to first principles tells the room that everything done so far was unexamined, so it only survives if you immediately name the assumptions you are throwing out. It also has a cost people gloss over: it is slow, and spending it on a decision where the standard industry answer would have been fine is how a quarter disappears.', 'Before we copy the vendor''s architecture wholesale, give me one pass from first principles. What do we actually need to be true here?', '[{"text":"Everyone in the industry does it one way and nobody in the room can say why. You want to propose spending a day working the problem out from scratch instead of inheriting the answer.","setting":"work"},{"text":"A cost model has been carried forward from an old project for three years, and you want to argue for rebuilding it out of what the components cost today.","setting":"work"},{"text":"You are weighing whether to buy or rent and realise every opinion you hold about it came from your parents.","setting":"life"},{"text":"A friend''s business plan copies a competitor''s pricing to the pound. You want to suggest working out what the thing costs to make and what it is worth to a customer, before looking at anyone else''s number.","setting":"life"}]', '["The order the work has to happen in, where each step stays blocked until the one before it is finished.","The founding values an organisation publishes and expects decisions to be weighed against. They are chosen rather than discovered, and they describe what the place would like to be.","The rules a system is never allowed to break, whatever else changes around it. They are written as constraints precisely so that any design violating one can be ruled out without a further argument about it.","The record of what went wrong on earlier projects, gathered so that the next team does not pay twice for the same mistake. Its whole authority comes from somebody having been through it before, which is also why it ages badly once the conditions change.","The earliest working version of a design, kept on file so that later arguments about why something is shaped the way it is can be settled by looking at what was originally intended. It carries weight in the room because it came first, not because anyone has since gone back and checked whether it still holds."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
