INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_continuum', 'continuum', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_continuum_0', 'e_continuum', 0, 'continuum', '["continua"]', 'A range with no natural joints in it, where the cases shade into one another and any line you draw is a decision rather than a discovery. Reaching for it in a room says the two camps arguing are looking at the same gradient from opposite ends.', 'It is a move against somebody''s categories, so it always lands as a challenge to whoever just proposed them. Used to avoid a call it is worse than useless: when the decision needs a threshold, saying the thing is a continuum without proposing where to cut reads as refusing to decide, and a sponsor will hear it that way. Do not use it where the steps are real either, because a pricing tier is not one.', 'Autonomy is not a switch, it is a continuum, and the real question is how far along it we are willing to be in the next release.', '[{"text":"A committee wants every agent sorted into autonomous or supervised, and each real system you have sits somewhere between the two.","setting":"work"},{"text":"A policy draft splits data into sensitive and not sensitive, and you have three examples that land on either side depending on who is asked.","setting":"work"},{"text":"A friend insists people are either morning people or night people, and you think the truth slides between the two rather than sitting in one box or the other.","setting":"life"},{"text":"Someone asks whether you speak Spanish. You can order dinner and you lose a phone call, so both yes and no are wrong answers.","setting":"life"}]', '["A stretch of uninterrupted running with no outage in it, quoted as the number of days since the last one.","A borderline case picked deliberately to test where a rule stops applying, so that whoever wrote the rule has to say out loud which side of it this one falls.","The position halfway between two stated extremes, arrived at by splitting the difference so that both camps can leave the room claiming they were partly heard. It is a settlement between people rather than a description of anything.","A ladder of named stages a team climbs in order, each rung carrying criteria you either meet or do not, and nobody standing on two rungs at once. It exists to tell people how far along they are, what the next step is going to cost and who has already made it.","A set of options priced in tiers, each one adding capability over the one below so that buyers sort themselves by what they are willing to pay. The gaps between the tiers are the whole design, and moving a feature from one tier to the next is a commercial decision rather than a technical one."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
