INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_persist_persistence', 'persist/persistence', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_persist_persistence_0', 'e_persist_persistence', 0, 'persist', '["persisted","persisting"]', 'To write something down where it will outlive whatever made it: a process restart, a page refresh, the end of a session. The noun for this concern is persistence, and the persistence layer is wherever that durable copy is kept.', 'Engineers hear a specific promise in it, that the thing is on durable storage and will come back after a crash, so do not use it for a value you are holding in a variable or a cache. It is transitive here, and that is the tell: you persist the state. Ordinary English uses the same word intransitively for keeping at something, so the team persisted says nothing at all about data, and we persisted the results will simply not parse for anyone non-technical in the room.', 'Right now the session only lives in memory. If the pod restarts we lose the whole conversation, so we need to persist it.', '[{"text":"A prototype loses everything the user typed the moment the browser is refreshed, and you are writing the ticket for what has to change.","setting":"work"},{"text":"In a design review someone is holding session state in memory on a single node, and you want to name the missing property before it goes near production.","setting":"work"},{"text":"An architect asks where the agent''s conversation history lives after a pod restarts, and you want the verb for putting it somewhere that survives one.","setting":"work"}]', '["To hold a connection open between requests so that the next one does not pay again for setting it up.","To keep a copy close to whoever is asking so that repeat reads come back fast, on the understanding that the copy is disposable and can be rebuilt from source whenever it is wrong.","To take a copy to a second location on a schedule so that there is something to restore from if the first one is lost. Nobody reads from that copy while things are going well, which is why it is so often found broken.","To flatten a structure into a run of bytes so that it can cross a network and be rebuilt into the same shape at the other end. The concern is the format on the wire, and both sides have to agree on it before anything useful moves.","To keep two systems in agreement as records change on either side, applying an agreed rule to decide which version wins when both of them moved at the same moment. Almost all of the work is in the reconciliation rather than in the writing, and almost all of the bugs are there too."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
