INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_persist_persistence_0_production', 's_persist_persistence_0', 'production', NULL, NULL, 134, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_persist_persistence_1', 'e_persist_persistence', 1, 'persistence', '["persistent"]', 'Staying with something well past the point where most people stop. It names the trait rather than the result, and always implies something was pushing back.', 'Praise for persistence quietly says the person got there by not stopping, which makes it a consolation prize when the work actually succeeded on merit: told to someone whose analysis was simply the best in the room, it damns them. Persistent about a person is worse again, because in most rooms that is the word for someone who will not take no for an answer.', 'That deal closed on persistence more than anything else. She went back to them four times after we had all written it off.', '[{"text":"A friend got into medical school on their third application, and you are raising a glass to whatever it was that got them there.","setting":"life"},{"text":"Your son has been failing the same climbing route every Saturday for a month, and today he got up it.","setting":"life"},{"text":"You are writing a reference for someone whose strongest quality is that they never let a thing drop.","setting":"work"},{"text":"A neighbour finally got the council to replace the broken streetlight after a year of letters nobody answered.","setting":"life"}]', '["The ability to come back quickly after a setback, more or less as you were before it.","A willingness to take on the work nobody else wants, usually because it is dull rather than because it is difficult.","Refusing to move from a position even once the evidence against it has been laid out, which reads as conviction from the inside and as obstinacy from anywhere else.","Care and attention to detail held at the same level over long stretches of work, so that the last page gets exactly the treatment the first one did, long after anybody would notice if it had not.","Confidence that a plan will come good in spite of what the people around you think, held firmly enough that you carry on funding it out of your own budget. It is a judgement about the odds, and it is either vindicated in the end or it is not."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
