INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_serialize', 'serialize', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_serialize_0', 'e_serialize', 0, 'serialize', '["serialization","serialized","serialise"]', 'To turn a structure that only exists in memory, an object or a graph or a trained model, into a flat run of bytes or text that can be stored or sent and then read back into the same shape at the other end.', 'The word has a second life in performance conversations, where serializing means forcing things through one at a time, the opposite of running them in parallel. Two engineers can talk past each other for ten minutes on that, so name the format or name the bottleneck and the ambiguity goes away. With a non-technical audience it lands as noise: say we save it in a form we can send.', 'The agent state has to be serialized before it goes on the queue, and half of these objects have no clean way to do that.', '[{"text":"An object holding your agent''s working state needs to go onto a message queue, and you are explaining what has to happen to it before it can.","setting":"work"},{"text":"Two services written in different languages need to exchange the same structure, and you are choosing the format both of them will write and read.","setting":"work"},{"text":"A trained model has to be written to a file so that another process can load it back in exactly the shape it was.","setting":"work"}]', '["To split a large payload into chunks small enough to travel, then put them back in order once they have all arrived.","To squeeze data into fewer bytes by taking out whatever repeats in it, so that the same content costs less to hold and less to move between systems.","To scramble data with a key before it leaves the network, so that anyone intercepting it holds something they cannot read. Only whoever has the matching key gets anything back out of it.","To check an incoming payload against an agreed schema and turn it away when a required field is missing or arrives as the wrong type, so that bad data fails at the door rather than three systems further downstream.","To give every record a unique identifier drawn in order, so that two rows written in the same instant can still be told apart afterwards and the number itself says roughly when each of them arrived. It is cheap to assign and awkward to change later."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
