INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_north_star', 'north star', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_north_star_0', 'e_north_star', 0, 'north star', '["north star metric","northstar"]', 'The one outcome you steer by, fixed while everything else stays negotiable. Its job in a room is to settle priority arguments before they happen, because it was agreed in advance; as a north star metric it is that outcome written as a single number.', 'The whole value is that there is exactly one. A deck with three north stars has none, and senior people read that as a team that has not chosen. It is also a direction rather than a commitment, so offering it as your quarterly goal hands someone a deadline for a thing you do not fully control. And it is common enough now that using it as decoration over an ordinary KPI is noticed; if the honest answer is a set of trade-offs, say that instead.', 'Time to a trustworthy answer is our north star for the year. If a feature does not move that, it waits.', '[{"text":"Three workstreams each have their own definition of success, and you want one outcome put above all of them and held there for the year.","setting":"work"},{"text":"A sponsor asks how you will choose between two features when both look good on paper, and you want to name the single measure that settles it.","setting":"work"},{"text":"You and your partner are weighing two cities, two jobs and a school, and you want to agree in advance on the one thing that matters most, so the decision is not made by whoever argues hardest at the time.","setting":"life"},{"text":"A friend is drowning in options for the year ahead and asks how you decide anything, and your honest answer is that you fix one thing and let everything else bend around it.","setting":"life"}]', '["The person named as accountable for a decision, so that when it has to be taken there is no argument about whose call it was.","The measure a team''s bonus is calculated from, which is why it quietly shapes what people do whether or not anybody intended it to.","The furthest milestone written into the roadmap today, understood by everyone in the room to be the point past which nothing has been planned in any detail yet and the dates are placeholders.","A benchmark lifted from whoever currently leads the market, used to set the bar for what counts as acceptable here. It moves whenever they move, which is both what makes it useful and the reason it can never settle an argument in the room for very long.","A published statement of what the organisation exists to do, written to survive any change of strategy and pitched broadly enough that nobody could ever be shown to have violated it. It gets repeated at all-hands and quoted back in interviews, and it decides nothing at all on a Tuesday afternoon."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
