INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_modality', 'modality', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_modality_0', 'e_modality', 0, 'modality', '["modalities"]', 'A kind of input or output a system works in: text, images, audio, video. It names the channel the information arrives or leaves in, not the subject matter and not the file format.', 'In an AI room it means the kind of data and nothing else. Reaching for it where ''format'' or ''channel'' would do - a delivery modality, a training modality - is the consulting usage, and to technical listeners it sounds like a plain word in a suit. Mixed rooms are the real risk: clinicians and consultants hear ''a way of doing something'' and follow you somewhere you did not intend to go.', 'The hard part isn''t the volume, it''s that the filings arrive in three modalities and only one of them is clean text.', '[{"text":"A sponsor asks why letting the assistant accept voice is not a small change. You want the term for the kind of input, so you can say the pipeline handles exactly one of them today.","setting":"work"},{"text":"You are writing an evaluation plan and need one heading that covers text, images and audio together as a single category of thing.","setting":"work"},{"text":"A colleague argues the product should answer in speech as well as on screen. You want one word for what they are proposing to add, rather than a list.","setting":"work"},{"text":"You are explaining to your father why his phone can now answer a question about a photograph as well as a typed question, and you want the word for those different kinds of input.","setting":"life"}]', '["The tone something is written in, from clipped and factual through to warm, chosen to suit whoever is reading it.","A named mode that switches a system between two ways of behaving, so that the same product can be strict for one customer and permissive for another.","The file format a thing happens to be stored in, which decides what can open it and how much room it takes, and which can be changed without altering a word of what it holds.","A permission level governing what a given person is allowed to do, from reading only, through editing, up to changing what everybody else is allowed to do. It travels with the person rather than with the material.","A stage of a pipeline, from ingestion at one end through to serving at the other, each with its own failure modes and its own owner. Work is handed from one to the next, and a problem is usually named after whichever stage it first showed up in."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
