INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_frontier', 'frontier', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_frontier_0', 'e_frontier', 0, 'frontier', '["frontier model","frontier models","frontier lab","frontier labs"]', 'The current edge of what AI systems can do, and by extension the handful of labs and models operating there. Calling something frontier places it in the most capable tier available, not merely the most recent.', 'It is a claim, and a checkable one. Applied to your own stack - a fine-tuned open model, a well-built agent - someone in the room will correct you, and the correction costs more than the word gained. It is also a moving line, so anything you call frontier today dates fast in writing. With a non-technical audience the older sense does the hearing for them: unexplored territory, the edge of the map, which turns a precise claim about capability into a vague metaphor about adventure.', 'We aren''t building at the frontier. We''re building on top of it, and that''s a completely different risk profile.', '[{"text":"An MD asks whether the supplier''s system is genuinely in the top tier of what exists or just the most recently announced, and you need the word for that tier.","setting":"work"},{"text":"You are drafting a risk note about depending on the very small number of organisations whose systems define what is currently possible, and you want the one-word label the industry uses for them.","setting":"work"},{"text":"You are arguing that a capability which only exists in research today will be ordinary in eighteen months, and you need a term for where it sits right now.","setting":"work"},{"text":"A friend outside the industry asks who is actually ahead in AI. You want the term for the handful of outfits at the edge of what is possible, rather than reciting company names.","setting":"life"}]', '["The furthest point a plan has been written out to, past which the work exists only as a heading and a rough number.","An early build handed to a small group before general release, so that the problems surface among people who have agreed to put up with them.","The boundary where two systems meet and hand data across, defined tightly enough that either side can be rebuilt without telling the other. It is a contract far more than it is a place.","A published limit on what a system is permitted to do, set by the people who carry the risk rather than by the people who built it, and written so that any breach shows up plainly afterwards instead of merely being suspected.","The set of capabilities promised in the next release, held out to customers as the reason to sign now rather than wait and see. It is a commitment about a date as much as about the work, and it gets quoted back at you the moment the date moves."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
