INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_eschew', 'eschew', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_eschew_0', 'e_eschew', 0, 'eschew', '["eschews","eschewed","eschewing"]', 'To avoid something deliberately and on principle, having had the option to take it. The choice, rather than the circumstance, is the whole point of the word.', 'It is a written word. Said out loud in a standup it sounds like you have swallowed a style guide, and even on the page it carries a moral edge: saying the team eschewed managed services claims a principle where ''chose not to use'' would have claimed only a decision. If the real reason was budget or timing, the word quietly overstates you, and anyone who knows the history will notice.', 'The paper eschews benchmark scores entirely and reports only task completion, which is either brave or very convenient.', '[{"text":"You are writing about a research group that left benchmark numbers out of a paper on purpose, and you want a verb that makes clear it was a choice rather than an oversight.","setting":"work"},{"text":"In an architecture note you want to record that the team turned down managed services as a matter of principle, not because of what they cost.","setting":"work"},{"text":"A friend has given up social media entirely and it is a stance rather than a lapse. You are writing about them and want the verb that honours the difference.","setting":"life"},{"text":"You are describing a novelist who refuses to write any dialogue at all, and you want a word that treats the refusal as deliberate craft.","setting":"life"}]', '["To fail to notice something that was there for the taking until it had gone.","To go without something because it was never within reach, so the outcome looks the same but nothing about it was actually decided.","To put something off until conditions improve, with every intention of coming back to it once the reason for waiting has gone away.","To turn a proposal down after a formal review, with the grounds minuted so that anybody bringing it back knows what would have to change first. The refusal belongs to the body rather than to a person.","To criticise something publicly and at length, usually a practice rather than a person, and in terms that make it awkward for anyone in the room to defend it. Whether you carry on doing it yourself is a separate question entirely."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
