INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_run_it_by_you_0_production', 's_run_it_by_you_0', 'production', NULL, NULL, 185, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_play_it_by_ear', 'play it by ear', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_play_it_by_ear_0', 'e_play_it_by_ear', 0, 'play it by ear', '["playing it by ear","played it by ear","play things by ear","play that by ear","play the rest by ear"]', 'To decide as you go, taking your lead from how things actually develop rather than from a plan settled in advance. It claims responsiveness, not the absence of thought.', 'It tells the room there is no plan, and how that lands depends entirely on who is in it. With friends it sounds relaxed; to a sponsor or a steering committee it sounds unprepared, and the usual reply is a request for the very plan you have just admitted you do not have. It is only defensible when the information you need genuinely does not exist yet, so name what you are waiting on - otherwise people file it as improvisation dressed up as flexibility.', 'We''ll fix the first two milestones and play the rest by ear until the vendor confirms their dates.', '[{"text":"A friend asks what time you will get to the party and whether you are staying for dinner, and you would rather not commit to either.","setting":"life"},{"text":"You are going to a city for two days with nothing booked past the first night, and a relative asks for your itinerary.","setting":"life"},{"text":"A director asks how you intend to handle the questions in a session where you do not yet know who is attending or what mood they will be in.","setting":"work"},{"text":"The supplier has not confirmed their dates, so the second half of the plan cannot be fixed yet, and you need a way to say so that does not sound unprepared.","setting":"work"}]', '["To carry on exactly as before, on the grounds that nothing has happened that would justify changing anything.","To follow an agreed process step by step, so that anybody auditing it afterwards can see each stage happened in the right order.","To copy what somebody else did in a situation that looked like this one, on the grounds that it worked for them and there is no time to design anything new.","To move quickly while the opportunity is still open, accepting that some of what you would normally check will have to be checked afterwards. The window closing is what sets the pace.","To make the call once and then defend it whatever happens next, so that everyone downstream can plan against it. Changing your mind later costs more than being wrong does, and that is the trade you are consciously making."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
