INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_advocate', 'advocate', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_advocate_0', 'e_advocate', 0, 'advocate', '["advocates"]', 'The person who argues your case, typically in rooms you are not in. Not the same as a supporter: the word carries the expectation that they will actually speak.', 'Naming someone as yours assigns them work they may not have agreed to, and in a hierarchy it can expose them - a director who is quietly helpful may not want to be described that way in front of their peers. Said of yourself about a cause it is fine; said of yourself about your own interests it sounds like a job title you invented. With lawyers in the room the word means counsel and will be heard that way first.', 'We don''t need everyone convinced. We need one advocate on that committee who''ll say it when we''re not in the room.', '[{"text":"You are told the committee will decide without you present, and you want the word for the one person in there who will make your case.","setting":"work"},{"text":"A mentor asks what you actually need from her, and the honest answer is someone who will speak for the work when you are not there to speak for it.","setting":"work"},{"text":"Your grandmother''s hospital appointments go badly when she attends alone, and you want the word for the role a family member plays by going with her.","setting":"life"},{"text":"You are describing a teacher who fought the school on your son''s behalf for two years, and you want the word for what she was to him.","setting":"life"}]', '["A neutral party brought in to settle a dispute between two sides who cannot resolve it themselves.","Someone senior who advises you in private, meeting you regularly to talk through your career and how to handle a difficult room.","A person appointed to test a proposal by arguing against it, so the weaknesses surface before a committee finds them. The opposition is assigned rather than sincerely held.","A colleague asked to give an account of your work to a panel deciding on a promotion, describing what they actually saw you do. What they contribute is evidence about the past, not pressure on the decision.","The senior person whose budget carries a piece of work and who answers to the board for whether it lands. It is a role defined by ownership of the money and the outcome, and it is usually written down somewhere on an org chart."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_advocate_0_recognition', 's_advocate_0', 'recognition', NULL, NULL, 189, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_advocate_0_reverse', 's_advocate_0', 'reverse', NULL, NULL, 190, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_advocate_0_production', 's_advocate_0', 'production', NULL, NULL, 191, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_advocate_1', 'e_advocate', 1, 'advocate for', '["advocate","advocating","advocating for","advocated for","advocacy"]', 'To argue actively and in the open for a position or a person, putting your own standing behind it. Stronger than agreeing with something: it means you are the one making the case.', 'It spends credibility, and it spends it visibly. Claiming it ties you to the outcome, so keep it for the two or three things a year you would still defend after they went wrong. Used about a small preference it inflates the stakes, and in a written self-assessment it reads as claiming credit unless the thing worked. There is also a floor: if all you did was agree in a meeting, someone who was there will remember that.', 'I advocated for keeping the evaluation in-house, and knowing what it cost us, I''d make the same call again.', '[{"text":"In a performance conversation you need a verb for the handful of times you put your own name behind an unpopular position rather than simply agreeing with it.","setting":"work"},{"text":"A junior colleague''s work was passed over and you intend to raise it with the panel yourself, at some cost to your own standing.","setting":"work"},{"text":"You are pressing the council to fix a dangerous junction by the school, and it has turned into a campaign rather than a complaint.","setting":"life"},{"text":"A relative needs a treatment the insurer keeps refusing, and somebody in the family has to make the case, loudly and repeatedly.","setting":"life"}]', '["To put a question to a formal vote so that the room goes on record, rather than settling it in conversation.","To set out both sides of a question evenly so a committee can choose, keeping your own preference deliberately out of it.","To carry out a decision you argued against once it has been taken, and to defend it outside the room as though it were your own. It is a discipline a committee expects, not a view you hold.","To sign off formally on something another team has proposed so that the work can proceed. The act is authority exercised at a gate, and it says nothing about whether you would have chosen it yourself.","To keep raising the same point in successive meetings until the objections stop being made, on the theory that persistence eventually reads as agreement. It describes a tactic for wearing a room down rather than the strength of anything actually said."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_advocate_1_recognition', 's_advocate_1', 'recognition', NULL, NULL, 192, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_advocate_1_reverse', 's_advocate_1', 'reverse', NULL, NULL, 193, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_advocate_1_production', 's_advocate_1', 'production', NULL, NULL, 194, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_pick_your_brain', 'pick your brain', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_pick_your_brain_0', 'e_pick_your_brain', 0, 'pick your brain', '["pick your brains","picking your brain","picked your brain","pick his brain","pick her brain","pick their brain","pick someone''s brain","pick a brain"]', 'To ask someone to talk through what they have learned, informally and in conversation, rather than making a request with a defined deliverable. What you want is in their head, not in any document.', 'It sounds casual while asking for open-ended time, and the whole cost falls on them. Sent cold to someone senior with no boundary on it - no length, no topic, no reason it has to be them - it reads as entitled, and to some it reads as asking them to do your thinking. Put twenty minutes and a specific question around it and it becomes easy to say yes to. The register is informal: right in a message to a colleague, wrong in a first approach to an MD you have never met.', 'You''ve done two of these migrations. Could I pick your brain for twenty minutes before we commit to a design?', '[{"text":"A colleague has already done two migrations like the one you are starting, and you want half an hour of informal conversation rather than a document from them.","setting":"work"},{"text":"You are messaging someone in another department whose experience you need, and you want a phrase that makes the request sound small and easy to accept.","setting":"work"},{"text":"A friend of a friend has renovated a flat like yours and you want an hour of their time and, more usefully, their mistakes.","setting":"life"},{"text":"Your cousin has just been through the visa process you are about to start, and you want to sit down with them and ask everything.","setting":"life"}]', '["To ask a colleague to read your draft closely and mark up everything wrong with it before it goes anywhere.","To question someone closely enough that the gaps in their account start to show, usually with other people in the room watching the exchange.","To bring someone onto a piece of work for a fixed period because of what they specifically know, with a scope and an end date attached. The arrangement is a booking of their time, not a conversation.","To collect views from a scattered group one at a time and write them up as a single position that can be circulated. The work is in the consolidation, and it is the write-up rather than any of the individual conversations that people end up quoting back at you.","To ask for something that costs the other person almost nothing to give: an introduction, a name, a link to something they have already written. The ask is kept deliberately small so that saying yes is easier than explaining a refusal, and it usually arrives with an apology attached."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
