INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_front_and_center', 'front-and-center', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_front_and_center_0', 'e_front_and_center', 0, 'front and center', '["front-and-center","front and centre","front-and-centre"]', 'In the most prominent position, where it cannot be missed. Usually said about what you deliberately put at the center of a document, a meeting, or a strategy.', 'It is a claim about visibility, not about importance, and the two come apart: whatever you put there also takes the questions, so the phrase is really a decision about exposure. That is doubly true of a person - being put there is not purely a compliment, because whoever stands there answers for the thing. The register is spoken and distinctly American, so in a formal board paper it reads breezier than everything around it.', 'Put the cost of doing nothing front and center. Everything else can go in the appendix.', '[{"text":"You are advising a colleague on a board deck, and the risk they buried on slide fourteen is the one thing the board most needs to see.","setting":"work"},{"text":"A sponsor asks what actually changed in the new strategy, and the honest answer is that a topic which used to sit in the appendix is now the first thing anybody sees.","setting":"work"},{"text":"You are hanging pictures and want one particular photograph in the most visible spot in the room rather than tucked off to the side.","setting":"life"},{"text":"A friend asks what you are prioritising now that the children have left home, and the answer is something you used to squeeze in around everything else.","setting":"life"}]', '["Placed first in a sequence of steps, so that everything after it depends on it being done.","Handled personally by the most senior person available rather than delegated down to whoever happens to have capacity that week.","Settled before any other item on the agenda can be discussed, because nothing that follows it makes sense until it is. It is a claim about sequence and about what blocks what.","Kept visible only to the people who actually need it and closed to everyone else, so that a sensitive number does not travel further than intended. The control is on the audience, and it is set deliberately.","Turned to face the customer rather than the back office, naming the part of a business a client actually touches: the people, the screens, the paperwork they sign. Everything behind that line is someone else''s problem to run, and it is staffed and priced differently."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
