INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_mold_breaker', 'mold breaker', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_mold_breaker_0', 'e_mold_breaker', 0, 'mold breaker', '["mold-breaker","moldbreaker"]', 'Someone or something that does not fit the established pattern for its category, and changes what people think the pattern is. Almost always said as praise.', 'It is a compliment in a room that rewards novelty and a warning label in a room that rewards precedent. Say it about a proposal to a steering committee and half of them hear unproven. Said about yourself it is unusable.', 'She''s a mold breaker for that seat, and that''s exactly the argument for hiring her.', '[{"text":"You are backing a candidate whose CV looks nothing like anyone else''s who has held the role, and you want the mismatch to sound like the reason to hire her.","setting":"work"},{"text":"A steering committee asks why one team keeps proposing things nobody else in the firm would have thought of. You want a compact phrase for what that team is.","setting":"work"},{"text":"You are introducing a new director whose whole appeal is that she does not resemble the last three people in the job.","setting":"work"},{"text":"A friend''s daughter skipped university to start a business, and you want a phrase for how far outside the family pattern that is.","setting":"life"},{"text":"You are describing a musician whose records sound like nothing else the genre produces.","setting":"life"}]', '["A template that everyone else is expected to follow once it has been approved as the standard.","Someone brought in to enforce consistency across teams that have each drifted into doing the same job a slightly different way.","An early adopter who takes a product on before it is proven, accepting the rough edges in exchange for being first. The risk is taken knowingly and the reward is timing.","A competitor that wins by undercutting everyone on price until the others stop defending the segment, then holds the ground it has taken. It is a strategy about cost, and it is rarely admired.","A person promoted well ahead of their peers, whose title now runs several years in front of their experience. It is meant as a compliment about pace, and it is heard by everyone else in the room as a statement about who is favored."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
