INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_mold_breaker_0_reverse', 's_mold_breaker_0', 'reverse', NULL, NULL, 217, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
