INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_hot_swap', 'hot-swap', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_hot_swap_0', 'e_hot_swap', 0, 'hot-swap', '["hot swap","hot-swapping","hot-swappable"]', 'To replace a running component without stopping the system around it. Extended well past hardware now: models, vendors and people exchanged mid-flight with nothing going dark.', 'The word promises no downtime, and that is a claim someone will hold you to on the day. Used about a person it is worse: hot-swap Priya onto that reads as people being interchangeable parts, which is fine between engineers and cold in front of her manager.', 'The provider sits behind an interface, so we can hot-swap the model without the application knowing.', '[{"text":"You are arguing the vendor contract is not a lock-in risk, because the provider sits behind an interface and can be exchanged without the application noticing.","setting":"work"},{"text":"An architect asks how you plan to move to the new embedding model without a maintenance window.","setting":"work"},{"text":"A sponsor asks what actually happens if the API you depend on doubles its price next quarter.","setting":"work"},{"text":"Someone on-call asks whether replacing the failed node means taking the cluster down first.","setting":"work"}]', '["To bring a system down cleanly inside a planned window, make the change, and then start it up again.","To run two versions side by side against the same traffic and compare what each produces before trusting either one of them in production.","To copy the state of a system at a point in time so that it can be put back exactly as it was if the change goes wrong. The copy is insurance, and it is taken before anything gets touched.","To keep a second machine idle and fully configured so that it takes over the moment the first one fails. It costs you the price of running two, and what it buys is the minutes between the failure and anyone noticing.","To move a task from whoever is stuck with it to whoever happens to have capacity, without changing anything about the task itself. It is a scheduling decision made about people rather than a change made to a system, and it gets announced in a standup rather than a change record."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_hot_swap_0_recognition', 's_hot_swap_0', 'recognition', NULL, NULL, 222, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_hot_swap_0_reverse', 's_hot_swap_0', 'reverse', NULL, NULL, 223, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_hot_swap_0_production', 's_hot_swap_0', 'production', NULL, NULL, 224, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_tectonic_shifts', 'tectonic shifts', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_tectonic_shifts_0', 'e_tectonic_shifts', 0, 'tectonic shift', '["tectonic shifts"]', 'Deep structural change in the conditions everyone is operating under, big enough to rearrange the landscape rather than move things around on it.', 'It is an enormous word and it inflates on contact with quarterly news. Senior people have heard it applied to five things that turned out to be nothing, so spend it only on change you could still point at in five years. It also implies slow and unstoppable, which makes it wrong for a shock.', 'The interesting thing isn''t this quarter''s numbers, it''s the tectonic shift in what clients now assume we''ll automate.', '[{"text":"You are opening a board update and want to frame three years of movement in client expectations as structural rather than a trend.","setting":"work"},{"text":"A sponsor keeps reacting to competitor announcements and you want to redirect him to the slower change underneath them.","setting":"work"},{"text":"You are writing a strategy memo about how the collapsing cost of inference has changed what is worth building at all.","setting":"work"},{"text":"A friend''s industry has changed so much since he trained for it that the job is not the same job, and you want a word for that scale of change.","setting":"life"},{"text":"You are describing to family how differently your city has come to feel over a decade.","setting":"life"}]', '["A sudden reversal that catches everyone unprepared and is over before anyone can respond.","A steady improvement in performance quarter after quarter, small each time and visible only when you look back across years.","A change of leadership that reorders who reports to whom while leaving the work itself exactly where it was. It moves boxes on a chart and not much else.","A rotating schedule that spreads coverage across time zones so somebody is always awake when a system breaks. It is an arrangement about people and hours rather than about markets.","Persistent friction between two parts of a business that keeps resurfacing in different forms: a missed handover this month, a disputed number the next. The cause never gets addressed, so the symptom keeps coming back."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_tectonic_shifts_0_recognition', 's_tectonic_shifts_0', 'recognition', NULL, NULL, 225, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_tectonic_shifts_0_reverse', 's_tectonic_shifts_0', 'reverse', NULL, NULL, 226, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_tectonic_shifts_0_production', 's_tectonic_shifts_0', 'production', NULL, NULL, 227, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_lend_itself', 'lend itself', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_lend_itself_0', 'e_lend_itself', 0, 'lend itself', '["lends itself","lend themselves","lends itself to"]', 'To have properties that make a particular use easy or natural. The subject is always the thing, never the person: the problem lends itself to the method, not the other way round.', 'It is a deliberately weak claim that people hear as an endorsement. It says good fit, not it will work, and that gap is your escape route later, which a sharp sponsor will notice you leaving open. The same phrase turns critical when what follows is bad, so the object sets the temperature.', 'Reconciliation lends itself to this — the rules are stable and every answer is checkable.', '[{"text":"An MD asks which of five processes you would automate first, and you want to say one of them is naturally shaped for it without promising the outcome.","setting":"work"},{"text":"You are pushing back on a proposed use case where the data is noisy and the answer is a judgement call, so the method fits it badly.","setting":"work"},{"text":"Reviewing a new metric, you want to warn that the way it is defined makes it very easy for teams to game.","setting":"work"},{"text":"A friend asks whether a novel would work as a film, and you think its structure is naturally suited to it.","setting":"life"},{"text":"You are choosing between two flats and one of them is shaped in a way that makes having people over easy.","setting":"life"}]', '["To hand something over for a fixed period on the understanding that it comes back in the same condition.","To add credibility to something simply by being associated with it, so that one name on a page changes how the rest of it gets read.","To adjust automatically when the conditions change, so that nobody has to intervene to keep the thing working. The behaviour belongs to the system, and the change in conditions is what triggers it.","To be the condition that has to hold before anything else can happen, so that when it is missing nothing downstream is possible at all. It is a claim about what depends on what, and it is usually discovered late.","To make a claim on another team''s people or budget on the grounds that the work is shared, which is the polite version of a fight about priorities. It is always addressed to whoever controls the resource rather than to the team that would do the work, and it gets settled well above both of them."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_lend_itself_0_recognition', 's_lend_itself_0', 'recognition', NULL, NULL, 228, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_lend_itself_0_reverse', 's_lend_itself_0', 'reverse', NULL, NULL, 229, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_lend_itself_0_production', 's_lend_itself_0', 'production', NULL, NULL, 230, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_bespoke', 'bespoke', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_bespoke_0', 'e_bespoke', 0, 'bespoke', '[]', 'Built for one customer or one case rather than taken off the shelf. In a platform conversation the word carries the cost with it: bespoke things never amortise.', 'The same word flatters a client and condemns a design, so know which room you are in. In front of a buyer it means premium and tailored; in an architecture review it means unrepeatable, unsupported and expensive to keep breathing. Say it about a colleague''s system and you have criticised it.', 'Every one of those dashboards is bespoke, which is exactly why nobody can maintain them.', '[{"text":"You are explaining to a sponsor why cost per client is not coming down: nothing built so far can be reused for the next one.","setting":"work"},{"text":"A client asks whether they get something built for them specifically or the same thing everyone else gets, and you want the flattering word for the first.","setting":"work"},{"text":"In an architecture review you want to name the pattern where six teams have each built their own one-off version of the same thing.","setting":"work"},{"text":"A friend had a suit made to his measurements rather than bought off the rack, and you are describing the difference to someone.","setting":"life"},{"text":"You are pricing a kitchen and the quote is enormous because every unit is made to fit that one room.","setting":"life"}]', '["Produced in volume to a single standard, so that every unit is interchangeable with every other.","Assembled out of standard parts in a new arrangement, which is a claim about the configuration rather than about the parts themselves.","Designed so the customer can extend it themselves after delivery, through settings and plug-in points the vendor deliberately left open. The work is done by whoever bought it.","Priced individually for each buyer according to what that buyer will bear, so two customers on identical contract terms can end up paying very different amounts and neither of them knows it.","Shipped before any formal specification exists, on the argument that requirements only become clear once somebody has something in front of them. It buys speed at the price of an argument later about what was actually agreed."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_bespoke_0_recognition', 's_bespoke_0', 'recognition', NULL, NULL, 231, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_bespoke_0_reverse', 's_bespoke_0', 'reverse', NULL, NULL, 232, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_bespoke_0_production', 's_bespoke_0', 'production', NULL, NULL, 233, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_in_pockets', 'in pockets', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_in_pockets_0', 'e_in_pockets', 0, 'in pockets', '["in pockets of"]', 'Present in scattered, isolated places rather than across the whole. It says the thing is real, has not spread, and that the places it exists in are not connected to each other.', 'It is honest and quietly deflating: a sponsor who hears adoption is in pockets hears not adopted. That makes it the right word when you are asking to connect the pockets and the wrong one when you are asking for more money to keep going as you are.', 'Adoption is real, but it''s in pockets — three teams live in it and nobody else has logged in since March.', '[{"text":"A sponsor asks whether the new tool has landed across the business. It has landed in four teams and nowhere else, and you want to be honest without sounding defeated.","setting":"work"},{"text":"You are writing a status note about where the new engineering practice has actually taken hold.","setting":"work"},{"text":"An MD asks whether data quality is a firm-wide problem. It is bad in a few specific places and fine everywhere else.","setting":"work"},{"text":"A friend asks whether a neighbourhood is safe. It mostly is, apart from a few isolated streets.","setting":"life"},{"text":"You are describing how mobile signal behaves on a route you drive: fine in scattered places, gone in between.","setting":"life"}]', '["Held back in reserve so that it can be released later, when the case for spending it is easier to make.","Spread thinly but evenly across the whole, so that everywhere has a little of it and nowhere has enough of it to matter to anyone.","Under one person''s control or influence to the point where their view decides the outcome, whatever the process on paper happens to say. It is said about people, and it is never said kindly.","Set aside inside a budget as contingency against something that has not happened yet, and quietly defended all year by whoever holds it. It is money that exists on the plan and is not meant to be spent.","Growing steadily outward from a single starting point, so that the edge moves further out each quarter and everything behind the edge is already covered. The spread is continuous, which is exactly what makes the progress easy to forecast."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_in_pockets_0_recognition', 's_in_pockets_0', 'recognition', NULL, NULL, 234, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_in_pockets_0_reverse', 's_in_pockets_0', 'reverse', NULL, NULL, 235, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_in_pockets_0_production', 's_in_pockets_0', 'production', NULL, NULL, 236, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_first_second_order_effects', 'first/second order effects', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_first_second_order_effects_0', 'e_first_second_order_effects', 0, 'first order effects', '["first-order effects","first order effect","first-order effect"]', 'The direct consequences of a change: what it does to the thing you changed. They are the ones you can see, the ones you planned, and usually the ones in the business case.', 'Naming something as first order is a promise that you have thought about what comes after it, and the next question in a senior room is always what comes after it. It also collides with first-order approximation, which means roughly, so in a mixed room say which you mean before someone hears you say the number is a guess.', 'The first order effect is that reviews get faster. What I actually care about is what happens to review quality once they do.', '[{"text":"A sponsor asks what the automation will do, and you want a term for the immediate, intended result before anyone asks what comes next.","setting":"work"},{"text":"In a design review you want to separate the direct consequence of a change from everything it sets off downstream.","setting":"work"},{"text":"You are writing a business case and want to label the obvious, countable benefit separately from the speculative ones.","setting":"work"},{"text":"You are talking about a tax on sugary drinks and want the name for what it does straight away to prices, as distinct from what happens after.","setting":"life"}]', '["The highest-priority items on a plan of work, the ones that get finished before anything else is started.","Costs a change imposes on people who were never party to it and are not compensated for it, which is why they rarely show up in anyone''s numbers.","Results large enough to be worth measuring at all, as against the ones that vanish into the noise. It is a threshold about size, and where you set it decides what gets reported and what does not.","The order in which dependent changes have to be made, so that nothing is switched on before the thing it relies on exists. It is a sequencing constraint, and getting it wrong is how a rollout stalls halfway through a weekend.","The group who receive a change before anyone else and whose experience decides whether it goes further: a floor, a region, a single desk. Who goes first is chosen deliberately, usually for tolerance rather than for how representative they are."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_first_second_order_effects_0_recognition', 's_first_second_order_effects_0', 'recognition', NULL, NULL, 237, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
