INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_first_second_order_effects_0_production', 's_first_second_order_effects_0', 'production', NULL, NULL, 239, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_first_second_order_effects_1', 'e_first_second_order_effects', 1, 'second order effects', '["second-order effects","second order effect","second-order effect"]', 'The consequences of the consequences: what happens once people and systems adapt to the first change. They arrive late, are rarely planned for, and are usually where the real result of a decision lives.', 'It is the easiest phrase in the language to use as a veto. Raise it and you should be able to name one, or you have added doubt to someone else''s proposal without paying anything for it. People notice when it only ever arrives on other people''s ideas.', 'The second order effect is the one I''d watch: once reviewers trust the tool, they stop reading the diffs.', '[{"text":"A proposal will obviously save time, and your worry is what people will quietly stop doing carefully once it does.","setting":"work"},{"text":"You are asking a team to think past the immediate benefit of a new incentive to how people will behave once they work out how it is measured.","setting":"work"},{"text":"In a risk review you want the phrase for harm that only appears after everyone has adapted to the new system.","setting":"work"},{"text":"A road near you is being widened, and you want the phrase for how traffic tends to grow to fill it.","setting":"life"},{"text":"A friend describes a rule their building introduced, and you want the term for what residents promptly started doing to get around it.","setting":"life"}]', '["The phase of a rollout that comes after the pilot, when a change finally goes to everyone who was not in the trial.","Risks a team identifies in advance, writes down, and asks a sponsor to accept formally, so that if one of them lands nobody can claim they were not told.","The extra cost of running something at a larger size: more storage, more support, more licences, all of it arriving in proportion to the growth. It is arithmetic rather than surprise, and a competent team can forecast it a year out.","Outcomes that were foreseen and then judged too small to act on, which is a decision somebody actually made rather than something the analysis missed. They tend to resurface in a review a year later, where the argument is about whether the judgement was reasonable at the time.","A follow-on tranche of funding released only once the first has proved out, so that money arrives in stages tied to evidence rather than all at once on the strength of a plan. It is a control a board puts on a programme it believes in but does not yet trust, and it is negotiated at the outset."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
