INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_verifiability_verifiable_rewards_1_production', 's_verifiability_verifiable_rewards_1', 'production', NULL, NULL, 254, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_substrate', 'substrate', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_substrate_0', 'e_substrate', 0, 'substrate', '[]', 'The underlying layer everything above it runs on and takes for granted. Not a component among others: the thing that has to be there before anything else is possible.', 'The word is borrowed from geology and biology and it arrives sounding grand, which is the trap. Calling your service a substrate claims other things genuinely depend on it, and someone in the room can check that; if two teams call your API, the honest word is shared service. It also flattens what it names, so describing another team''s product that way can land as demoting them to plumbing.', 'Identity and audit are substrate. Nobody should be building either of them per product.', '[{"text":"You are arguing that authentication and logging get built once for everyone instead of separately by each product team.","setting":"work"},{"text":"A director asks what the platform team actually delivers, and you want a word for the layer everything else simply assumes is there.","setting":"work"},{"text":"In an architecture review you want to name the foundation that would have to be replaced first if you ever changed cloud providers.","setting":"work"},{"text":"Talking with a friend about how much of ordinary daily life quietly rests on the electricity grid.","setting":"life"},{"text":"You are describing a shared language as the thing an entire culture''s humour is built on top of.","setting":"life"}]', '["Scaffolding put up to get something built and taken away again once the thing stands on its own.","The outermost layer users actually touch, where a system''s decisions turn into buttons and screens and everything underneath is hidden from view.","A shared vocabulary that lets separate teams describe the same data in the same words, so a number means one thing in every report it turns up in and the arguments about definitions stop.","A part that can be pulled out and replaced while the system around it keeps running, which is a property of how it is attached rather than of where it sits. What it buys you is the ability to change something without a window.","The smallest set of features that lets a product go in front of real users at all, chosen so that what comes back is a judgement about the idea rather than about the polish. Everything left out is a bet that nobody will miss it yet."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substrate_0_recognition', 's_substrate_0', 'recognition', NULL, NULL, 255, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substrate_0_reverse', 's_substrate_0', 'reverse', NULL, NULL, 256, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substrate_0_production', 's_substrate_0', 'production', NULL, NULL, 257, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_dogfooding', 'dogfooding', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_dogfooding_0', 'e_dogfooding', 0, 'dogfooding', '["dogfood","eat your own dog food","eating our own dog food"]', 'Using your own product for real work before asking anyone else to. The point is not that you tested it; the point is that you feel its defects the way a customer would, on work you are judged on.', 'The bar is higher than people claim. Installing your own tool is not dogfooding unless something you care about breaks when it breaks. It is also an internal word with a self-congratulatory edge, and said to a client it raises the question it was meant to settle: if you had to tell me you use it, who else does?', 'We''re not putting the assistant on anyone''s desk until we''ve been dogfooding it for a month ourselves.', '[{"text":"You are arguing the team should run its own weekly reporting on the platform it wants to sell internally, before anyone outside is asked to touch it.","setting":"work"},{"text":"A sponsor asks how you will find the rough edges before a client does.","setting":"work"},{"text":"Someone proposes a launch date and you want the phrase for the month of real internal use you want in front of it.","setting":"work"},{"text":"You are explaining why one team''s tool has an unusually good workflow: they live inside it every single day.","setting":"work"}]', '["Running a limited release to a small group of friendly customers who have agreed to put up with rough edges.","Testing a system with synthetic traffic shaped to look like the real thing, so that load can be pushed well past anything a real day would ever produce.","Reviewing a competitor''s product feature by feature and scoring it against your own, usually in a grid that ends up in front of a board. The exercise says more about what you fear than about what they built.","Trialling a change on a small share of live users while everyone else stays on the old path, so that any difference in behaviour between the two groups can be attributed to the change rather than to the week it happened in.","Giving influential outsiders early access in exchange for their feedback and, if it goes well, their public support. What is being bought is a set of names willing to be quoted on the day of launch, and the feedback is usually the smaller half of the deal."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
