INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_squarely_0_production', 's_squarely_0', 'production', NULL, NULL, 263, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_fan_out', 'fan-out', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_fan_out_0', 'e_fan_out', 0, 'fan-out', '["fanout","fan out","fans out"]', 'One piece of work splitting into many parallel branches: a single request becoming dozens of calls that all have to come back before there is an answer. The multiplier is the point.', 'In messaging and feed systems the same word means one write being delivered to many readers, so in a mixed room say which you mean before the conversation quietly forks. And whichever you mean, people hear the multiplier rather than the parallelism: say it to whoever pays the bill and the next question is cost, so arrive with the number.', 'One question fans out to eight tool calls, so a thousand users an hour is not a thousand requests an hour.', '[{"text":"An architect asks why a single user question costs so much to serve, and the answer is the number of parallel calls each one triggers.","setting":"work"},{"text":"You are describing a design where a request is split across many workers that must all return before an answer exists.","setting":"work"},{"text":"A sponsor asks why the inference bill grew much faster than the user count did.","setting":"work"},{"text":"In a review you want the term for the multiplier between one incoming request and the downstream calls it sets off.","setting":"work"}]', '["Many small requests gathered up and sent as a single call, so the cost of the round trip gets paid once.","The time a request spends waiting in a queue before anything starts working on it, which is usually most of what a user experiences as slowness.","Incoming traffic spread evenly across a row of identical servers so that none of them takes more than its share, which is what lets you add capacity by adding boxes rather than by making any one box bigger.","The share of calls that fail and are sent again automatically, invisible on a good day and the whole problem on a bad one, because the retries all arrive at exactly the moment the system has least room left for them.","Results arriving from several different sources and being folded into a single answer, where the hard part is deciding what to do when two of them disagree. It is the last step of a pipeline rather than the first, and it is where most of the arguments about correctness actually happen."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
