INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_panopticon', 'panopticon', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_panopticon_0', 'e_panopticon', 0, 'panopticon', '["panoptic"]', 'A structure where everyone can be watched at any moment and nobody knows when they are, so they behave as though always observed. Used about surveillance systems and the self-censorship they produce.', 'This is a criticism, not a description. It carries Foucault''s argument about power. If you only mean thorough monitoring or good observability, panopticon reads as an accusation and changes the temperature of the room.', 'If every prompt is logged and reviewed, we''ve built a panopticon and people will stop experimenting.', '[{"text":"You are arguing against logging every internal AI interaction, and your point is that people behave differently when they might be watched.","setting":"work"},{"text":"A colleague proposes recording all agent sessions for quality review. You want a word for what that does to how people use the tool.","setting":"work"},{"text":"You are describing a neighbourhood where every corner has a camera, and how differently people carry themselves there.","setting":"life"},{"text":"Talking about social media with a friend, you want the word for a place whose power comes from the possibility of being watched rather than the fact of it.","setting":"life"}]', '["An organisation where information flows freely in every direction, so anyone can see what anyone else is working on.","A single point that all traffic has to pass through, which makes it the natural place to apply a rule and the one place a failure takes everything else down with it.","A record kept in full and retained for years because a regulator may one day ask for it, complete enough that a decision taken in 2019 can be reconstructed line by line. Nobody consults it in the meantime.","A room in which the decisions of one team are examined by another that had no hand in making them, on the argument that fresh eyes catch what familiar ones stop seeing. It costs a week, and it is defended as the price of not repeating an expensive mistake.","The room from which a plant or a network is actually operated: live telemetry on the wall, alarms that route to a named person, and the ability to intervene directly on the thing being displayed. What defines it is the hand on the switch rather than the eye on the screen."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_panopticon_0_recognition', 's_panopticon_0', 'recognition', NULL, NULL, 267, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_panopticon_0_reverse', 's_panopticon_0', 'reverse', NULL, NULL, 268, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_panopticon_0_production', 's_panopticon_0', 'production', NULL, NULL, 269, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_disparage', 'disparage', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_disparage_0', 'e_disparage', 0, 'disparage', '["disparaging","disparagement"]', 'To speak about someone or something in a way that lowers it, usually by a passing remark or faint praise rather than open attack. It describes a manner of speaking, not a disagreement.', 'It mostly appears as an accusation or a denial, and the denial never works: I don''t want to disparage the previous team announces precisely what you are about to do. Its other trap is defensive — calling someone''s honest criticism disparagement is a way of dodging the criticism, and senior people can see you do it.', 'I''m not trying to disparage the previous team — they were solving a different problem with a fifth of the budget.', '[{"text":"You want to criticise a decision without it sounding like you are running down the people who made it.","setting":"work"},{"text":"A friend keeps making small remarks that quietly diminish his partner''s job, and you are describing the pattern to someone else.","setting":"life"},{"text":"A relative constantly talks down the town you moved to, and you want a precise word for what he is doing rather than just calling him rude.","setting":"life"},{"text":"You are reading a review that never quite attacks the book but leaves it smaller than it found it.","setting":"life"},{"text":"Someone asks why you left a group chat, and the honest answer is the constant belittling of one member.","setting":"life"}]', '["To dispute a claim by putting contrary evidence in front of the room and letting the numbers do the work.","To overstate how important something is so that it gets attention it would not otherwise be given, which costs you credibility the second time.","To withdraw public support from a person or a project you previously backed. It is a change of position rather than a choice of words, and the absence of the endorsement is noticed more than any sentence would have been.","To circulate information you know to be untrue in order to damage someone, which is a question about the facts rather than about the tone. It is also the version of this that ends up involving a lawyer.","To pin responsibility for a collective failure on one named person so that the review can be closed and everyone else can get back to work. It is usually done without malice and it is almost always the wrong answer, because the conditions that produced the failure are still there for whoever fills the seat next."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_disparage_0_recognition', 's_disparage_0', 'recognition', NULL, NULL, 270, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_disparage_0_reverse', 's_disparage_0', 'reverse', NULL, NULL, 271, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_disparage_0_production', 's_disparage_0', 'production', NULL, NULL, 272, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_diaspora', 'diaspora', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_diaspora_0', 'e_diaspora', 0, 'diaspora', '["diasporic"]', 'A people scattered from a homeland who keep a tie to it, and the fact of that scattering. The word carries the history of why they left, which is usually not by choice.', 'The weight is the whole risk. Stretched to any dispersed group — ex-colleagues of a firm, alumni of a team, people who left a project — it sounds glib to anyone whose family actually belongs to one, and that person is more often in the room than not. If you mean a network of former employees, say alumni network.', 'The growth story there is remittances — money moving back through the diaspora — not domestic demand.', '[{"text":"A friend describes a wedding where everyone''s parents left the same country decades ago and almost nobody has been back.","setting":"life"},{"text":"You are explaining why one neighbourhood has three bakeries selling the same bread from one small region.","setting":"life"},{"text":"You are reading about a language kept alive abroad long after it faded where it began.","setting":"life"},{"text":"You are explaining to a colleague that a country''s economy runs largely on money sent home by people living overseas.","setting":"work"}]', '["The arrival of newcomers into one country, counted at the border and argued about in its politics.","The blending of two cultures into a third that belongs wholly to neither, visible first in the food and in the language.","A community that shares a trade rather than an origin, held together by the work itself and by the annual conference where its members recognise each other and then go home again.","A group that has withdrawn from the society around it on purpose and keeps its own rules inside a boundary it drew itself. What defines it is the choosing, and the boundary is maintained from the inside.","The movement of people out of the countryside and into cities inside one country, which reshapes both ends of it within a generation: labour arrives where the work is and the villages empty out behind it. It is measured by economists more often than it is remembered by families."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_diaspora_0_recognition', 's_diaspora_0', 'recognition', NULL, NULL, 273, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_diaspora_0_reverse', 's_diaspora_0', 'reverse', NULL, NULL, 274, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_diaspora_0_production', 's_diaspora_0', 'production', NULL, NULL, 275, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_sleuthing_out', 'sleuthing (out)', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_sleuthing_out_0', 'e_sleuthing_out', 0, 'sleuthing', '["sleuth","sleuth out","sleuthing out","sleuthed out"]', 'Patient, curious digging for something that is not hidden on purpose but is written down nowhere either. It is piecing an answer together from scraps instead of asking someone for it.', 'The word is light and slightly playful, which cuts both ways. It is generous about a colleague''s persistence, and it lets people off when the real reason you had to dig is that someone would not tell you. Said about your own week to a sponsor, it can turn two days of genuine analysis into a hobby.', 'Nobody could tell me which system owned that field, so I spent Tuesday sleuthing it out of the commit history.', '[{"text":"You spent a day working out which team owns an undocumented field by reading commit history and four-year-old tickets.","setting":"work"},{"text":"You want to credit a colleague who found the cause of a recurring cost spike that nobody had been able to explain.","setting":"work"},{"text":"A director asks how you established that two suppliers on the list are actually the same company.","setting":"work"},{"text":"You finally worked out which neighbour has been leaving flowers in the stairwell.","setting":"life"},{"text":"From photographs and a few names, you pieced together where your grandmother lived before the family moved.","setting":"life"}]', '["Following an established procedure step by step in order to confirm a result that was already expected.","Interviewing people one after another until somebody finally says what happened, where the work is in the pressure rather than in the reading.","Stripping the sensitive details out of a document before it is circulated more widely, so that the argument in it can travel without the names, the numbers and the client still attached to it.","Querying a system for the records that match a set of conditions you already know how to state, which is fast, repeatable, and exactly as good as the question you thought to ask in the first place.","Watching activity closely enough to catch somebody in the act, with the intention formed well before the looking starts. What separates it from ordinary curiosity is that the conclusion is already in place and the observation is only there to supply evidence for it."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_sleuthing_out_0_recognition', 's_sleuthing_out_0', 'recognition', NULL, NULL, 276, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_sleuthing_out_0_reverse', 's_sleuthing_out_0', 'reverse', NULL, NULL, 277, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_sleuthing_out_0_production', 's_sleuthing_out_0', 'production', NULL, NULL, 278, '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO NOTHING;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_ephemeral', 'ephemeral', NULL, '[]', 'ready', '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, prompt_version, created_at, updated_at) VALUES ('s_ephemeral_0', 'e_ephemeral', 0, 'ephemeral', '["ephemerality"]', 'Lasting only briefly, and meant to. In infrastructure it names things created for one use and destroyed after it — containers, tokens, workspaces — where the short life is the design, not a limitation.', 'In a technical room it is a claim rather than a description: say a workspace is ephemeral and the next questions are about the logs, the cache and whatever it wrote on its way out. Everywhere else it is a slightly literary word, elegant in writing and a little precious said out loud about a colleague''s short tenure or a passing mood.', 'Every agent run gets an ephemeral workspace — it exists for the task and nothing survives it.', '[{"text":"You are describing a design where each run gets a fresh environment that is destroyed the moment it finishes.","setting":"work"},{"text":"A security reviewer asks how long the credentials the agent uses stay valid, and the answer is nine minutes.","setting":"work"},{"text":"You are justifying why you do not want a permanent copy of the intermediate data kept anywhere.","setting":"work"},{"text":"You are telling a friend that the best thing about that festival is how the whole town it builds is gone by Monday.","setting":"life"},{"text":"You want a word for how quickly a mood of collective optimism came and went.","setting":"life"}]', '["Happening at intervals nobody can predict, so you cannot plan around it and have to be ready for it at any hour.","Held only in memory and never written down to disk, which is what makes it quick to read and impossible to recover once the machine has restarted.","Recreated automatically after a failure without anyone being paged, so that the system returns to its intended shape on its own. What is promised is that the desired state is written down somewhere and continuously enforced.","Too small in scale or in consequence to be worth reporting, so it gets aggregated away well before the number reaches anyone senior. The threshold is set deliberately, and the argument in a review is nearly always about where it was set rather than about the events themselves.","Rebuilt from scratch on every change rather than edited in place, so that no server ever accumulates a history of adjustments nobody remembers making. It is a discipline about how change gets applied, and the benefit of it is that what is running always matches what is written in the repository."]', 2, '2026-08-23T11:35:54.559Z', '2026-08-23T11:35:54.559Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
